import EntityDetailsDropdown from '../../../../../components/Shared/EntityDropdown/EntityDetailsDropdown.tsx';
import { EllipsisWithTooltip } from '../../../../../components/Shared/Tables/TableV1.tsx';
import { BadgeCell, TextCell } from '../../../../../components/ui';
import { RECORD_COPY } from '../../constants/recordCopy';
import {
  formatRecordCreatedAt,
  formatRecordDateValue,
  getRecordLeadDisplayId,
  getRecordPhoneNumber,
  hasAiChatData,
  hasAudioSummaryTranscript,
  isCommentColumnKey,
} from '../../utils/recordInteractiveColumnUtils';
import RecordCommentCell from './RecordCommentCell';
import {
  buildEntityQueryParamsForRow,
  getFieldDataFromRow,
  getParentStatusConfig,
  getRawLead,
  isFieldReadOnly,
} from '../../utils/recordInlineEditUtils';

const ENTITY_CELL_SX = {
  mb: 0,
  mt: 0,
  minWidth: 130,
  maxWidth: 200,
  '& .MuiOutlinedInput-root': {
    height: 28,
    borderRadius: '999px',
    fontSize: '0.75rem',
    padding: '0 8px',
    backgroundColor: 'transparent',
    '& fieldset': {
      borderColor: 'divider',
      borderWidth: '0.5px',
    },
    '&:hover fieldset': {
      borderColor: 'primary.main',
    },
  },
  '& .MuiInputBase-input': {
    padding: '0 4px',
    fontSize: '0.75rem',
    lineHeight: 1,
  },
  '& .MuiInputLabel-root': {
    display: 'none',
  },
  '& .MuiAutocomplete-endAdornment': {
    right: 4,
  },
};

const EMPTY_VALUE = '—';

function stopRowClick(event) {
  event.stopPropagation();
}

function InteractiveActionLink({
  label,
  onClick,
  disabled = false,
}) {
  if (label == null || label === '') {
    return <TextCell value={EMPTY_VALUE} />;
  }

  return (
    <Typography
      variant="body2"
      color={disabled ? 'text.primary' : 'primary.main'}
      className="record-cell-action"
      sx={{ cursor: disabled ? 'default' : 'pointer' }}
      onClick={(event) => {
        stopRowClick(event);
        if (!disabled) {
          onClick?.(event);
        }
      }}
    >
      {label}
    </Typography>
  );
}

function RecordStatusCell({
  row,
  fieldMeta,
  typeOfStatusList,
  onRequestStatusUpdate,
  canEdit,
}) {
  const fieldData = getFieldDataFromRow(row, fieldMeta.key_name);
  const statusOptions = typeOfStatusList[fieldMeta.key_name] ?? [];
  const targetVal = fieldData?.status_config?.status_name || fieldData?.value;
  const currentValue = statusOptions.find(
    (entry) =>
      entry?.status_id === fieldData?.status_config?.status_id ||
      (targetVal && (entry?.status_name === targetVal || entry?.name === targetVal))
  ) ?? (targetVal ? { status_name: targetVal, name: targetVal } : { status_name: 'Select' });

  return (
    <Box onClick={stopRowClick}>
      <StatusDropdown
        options={statusOptions}
        value={currentValue}
        onChange={(selected) => onRequestStatusUpdate(row, selected, fieldMeta)}
        labelKey="status_name"
        valueKey="status_id"
        disabled={isFieldReadOnly(fieldMeta, canEdit)}
      />
    </Box>
  );
}

function RecordSubStatusCell({
  row,
  fieldMeta,
  typeOfStatusList,
  onRequestStatusUpdate,
  canEdit,
}) {
  const fieldData = getFieldDataFromRow(row, fieldMeta.key_name);
  const parentFieldData = getFieldDataFromRow(row, fieldMeta.status_parent_key);
  const parentVal = parentFieldData?.status_config?.status_name || parentFieldData?.value;
  const parentConfig = getParentStatusConfig(row, fieldMeta.status_parent_key);
  const parentStatusId =
    parentConfig?.status_id ||
    (typeOfStatusList[fieldMeta.status_parent_key] ?? []).find(
      (s) => s?.status_name === parentVal || s?.name === parentVal
    )?.status_id;

  const allOptions = typeOfStatusList[fieldMeta.key_name] ?? [];
  const optionsData = parentStatusId
    ? allOptions.filter((entry) => entry?.status_id === parentStatusId)
    : allOptions;

  const targetVal = fieldData?.status_config?.name || fieldData?.status_config?.status_name || fieldData?.value;
  const currentValue = optionsData.find(
    (entry) =>
      entry?.sub_status_id === fieldData?.status_config?.sub_status_id ||
      (targetVal && (entry?.name === targetVal || entry?.status_name === targetVal))
  ) ?? (targetVal ? { name: targetVal, status_name: targetVal } : { name: 'Select' });

  return (
    <Box onClick={stopRowClick}>
      <StatusDropdown
        options={optionsData}
        value={currentValue}
        onChange={(selected) => onRequestStatusUpdate(row, selected, fieldMeta)}
        labelKey="name"
        valueKey="sub_status_id"
        disabled={isFieldReadOnly(fieldMeta, canEdit)}
      />
    </Box>
  );
}

function RecordEntityCell({
  row,
  fieldMeta,
  onEntityChange,
  canEdit,
}) {
  const fieldData = getFieldDataFromRow(row, fieldMeta.key_name);
  const entityData = fieldData?.entity_data;
  const currentValue = entityData
    ? { _id: entityData._id, value: entityData.value }
    : fieldData?.value
      ? { _id: fieldData.value, value: fieldData.value }
      : null;
  const queryParams = buildEntityQueryParamsForRow(fieldMeta, row);

  return (
    <Box onClick={stopRowClick}>
      <EntityDetailsDropdown
        value={currentValue}
        onChange={(selectedOption) => onEntityChange(row, fieldMeta, selectedOption)}
        entityFormId={fieldMeta?.entity?._id ?? ''}
        label=""
        disabled={isFieldReadOnly(fieldMeta, canEdit)}
        displayField="value"
        selectedEntityFields={fieldMeta?.selectedEntityFields ?? []}
        queryParams={queryParams}
        sx={ENTITY_CELL_SX}
      />
    </Box>
  );
}

function RecordFileCell({ value }) {
  if (!value) {
    return <TextCell value={EMPTY_VALUE} />;
  }

  if (typeof value === 'object' && value instanceof File) {
    return (
      <Typography
        variant="body2"
        color="primary.main"
        className="record-cell-action"
        sx={{ cursor: 'pointer' }}
        onClick={(event) => {
          stopRowClick(event);
          const url = URL.createObjectURL(value);
          window.open(url, '_blank', 'noopener,noreferrer');
        }}
      >
        View
      </Typography>
    );
  }

  if (typeof value === 'string' && value.startsWith('https')) {
    return (
      <Typography
        variant="body2"
        color="primary.main"
        className="record-cell-action"
        sx={{ cursor: 'pointer' }}
        onClick={(event) => {
          stopRowClick(event);
          window.open(value, '_blank', 'noopener,noreferrer');
        }}
      >
        View
      </Typography>
    );
  }

  return <TextCell value={String(value)} maxWidth="100%" />;
}

function OptionColorBadge({ label, color }) {
  if (!color) {
    return <BadgeCell label={label} variant="neutral" size="sm" />;
  }

  return (
    <Box
      component="span"
      sx={{
        display: 'inline-flex',
        alignItems: 'center',
        px: 1,
        py: 0.25,
        borderRadius: '999px',
        bgcolor: color,
        color: 'text.primary',
        fontSize: '0.6875rem',
        fontWeight: 600,
        lineHeight: 1.4,
        letterSpacing: '0.02em',
        maxWidth: '100%',
      }}
    >
      {label}
    </Box>
  );
}

function RecordStaticColumnCell({
  row,
  value,
  fieldMeta,
  columnActions = {},
}) {
  const keyName = fieldMeta?.key_name;

  if (keyName === 'lead_id') {
    const label = getRecordLeadDisplayId(row) || value;
    return (
      <InteractiveActionLink
        label={label || EMPTY_VALUE}
        onClick={() => columnActions.onViewRecord?.(row)}
      />
    );
  }

  if (keyName === 'phone_number') {
    const phone = getRecordPhoneNumber(row) || value;
    if (!phone) {
      return <TextCell value={EMPTY_VALUE} />;
    }

    return (
      <InteractiveActionLink
        label={phone}
        disabled={!columnActions.canOpenWebForm}
        onClick={() => columnActions.onOpenWebForm?.(row)}
      />
    );
  }

  if (keyName === 'created_at') {
    const rawLead = getRawLead(row);
    const formatted = formatRecordCreatedAt(value || rawLead?.created_at);
    return <TextCell value={formatted || EMPTY_VALUE} maxWidth="100%" />;
  }

  if (isCommentColumnKey(keyName)) {
    return (
      <RecordCommentCell
        row={row}
        value={value}
        canAddComment={columnActions.canAddComment}
        onOpenComment={columnActions.onOpenComment}
      />
    );
  }

  if (keyName === 'audio_summary') {
    const label = hasAudioSummaryTranscript(row)
      ? RECORD_COPY.columnCells.audioUpload
      : RECORD_COPY.columnCells.audioView;

    return (
      <InteractiveActionLink
        label={label}
        onClick={() => columnActions.onOpenAudioSummary?.(row)}
      />
    );
  }

  if (keyName === 'aichat') {
    if (!hasAiChatData(row)) {
      return <TextCell value={EMPTY_VALUE} />;
    }

    return (
      <InteractiveActionLink
        label={RECORD_COPY.columnCells.aiChatAction}
        onClick={() => columnActions.onOpenAiChat?.(row)}
      />
    );
  }

  return null;
}

function RecordDefaultCell({ value, fieldMeta, optionColorsByAlias = {} }) {
  if (value == null || value === '') {
    return <TextCell value={EMPTY_VALUE} />;
  }

  const isDateField =
    fieldMeta?.data_type === 'DATE'
    || fieldMeta?.key_name === 'created_at'
    || (typeof value === 'string' && /^\d{4}-\d{2}-\d{2}/.test(value));

  if (isDateField) {
    return (
      <TextCell
        value={formatRecordDateValue(value, fieldMeta) || EMPTY_VALUE}
        maxWidth="100%"
      />
    );
  }

  if (['DROPDOWN', 'RADIO', 'CHECKBOX'].includes(fieldMeta?.key_type)) {
    const colorMap = optionColorsByAlias[fieldMeta?.key_name] || {};
    const rawValues = Array.isArray(value)
      ? value
      : typeof value === 'string'
        ? value.split(',').map((entry) => entry.trim()).filter(Boolean)
        : [value];

    const labels = rawValues
      .map((entry) => (typeof entry === 'object' ? (entry.label ?? entry.name ?? entry.value) : entry))
      .filter(Boolean)
      .map(String);

    if (labels.length === 0) {
      return <TextCell value={EMPTY_VALUE} />;
    }

    if (labels.length === 1) {
      return <OptionColorBadge label={labels[0]} color={colorMap[labels[0]]} />;
    }

    return (
      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
        {labels.map((label) => (
          <OptionColorBadge key={label} label={label} color={colorMap[label]} />
        ))}
      </Box>
    );
  }

  if (fieldMeta?.key_type === 'TEXTAREA') {
    return <TextCell value={String(value)} maxWidth="100%" />;
  }

  if (fieldMeta?.type === 'badge') {
    return <BadgeCell label={String(value)} variant="neutral" />;
  }

  if (typeof value === 'object') {
    return <TextCell value={JSON.stringify(value)} maxWidth="100%" />;
  }

  return <TextCell value={String(value)} maxWidth="100%" />;
}

export default function RecordTableCell({
  row,
  value,
  column,
  typeOfStatusList = {},
  optionColorsByAlias = {},
  canEdit = false,
  columnActions = {},
  onRequestStatusUpdate,
  onEntityChange,
}) {
  const fieldMeta = {
    ...(column?.fieldMeta ?? {}),
    key_name: column?.fieldMeta?.key_name ?? column?.key,
  };

  const staticCell = RecordStaticColumnCell({
    row,
    value,
    fieldMeta,
    columnActions,
  });

  if (staticCell) {
    return staticCell;
  }

  if (fieldMeta.key_type === 'ENTITY') {
    return (
      <RecordEntityCell
        row={row}
        fieldMeta={fieldMeta}
        onEntityChange={onEntityChange}
        canEdit={canEdit}
      />
    );
  }

  if (fieldMeta.key_type === 'FILE') {
    return <RecordFileCell value={value} />;
  }

  if (fieldMeta.key_type === 'DROPDOWN' && fieldMeta.statusOption === 'is_sub_status') {
    return (
      <RecordSubStatusCell
        row={row}
        fieldMeta={fieldMeta}
        typeOfStatusList={typeOfStatusList}
        onRequestStatusUpdate={onRequestStatusUpdate}
        canEdit={canEdit}
      />
    );
  }

  if (fieldMeta.key_type === 'DROPDOWN' && fieldMeta.statusOption === 'is_status') {
    return (
      <RecordStatusCell
        row={row}
        fieldMeta={fieldMeta}
        typeOfStatusList={typeOfStatusList}
        onRequestStatusUpdate={onRequestStatusUpdate}
        canEdit={canEdit}
      />
    );
  }

  return (
    <RecordDefaultCell
      value={value}
      fieldMeta={{ ...fieldMeta, type: column?.type }}
      optionColorsByAlias={optionColorsByAlias}
    />
  );
}
