/**
 * Scrolls chat feed to the latest message after layout (templates expand after first paint).
 */
export function scrollLeadChatFeedToBottom(element) {
  if (!element) return;

  const apply = () => {
    element.scrollTop = element.scrollHeight;
  };

  apply();
  requestAnimationFrame(() => {
    apply();
    requestAnimationFrame(apply);
  });
}
