import { applyIncomingMessage } from '../sockets/handlers/handleIncomingMessage';
import { leadChatBotNumbersMatch, leadChatPhonesMatch } from './leadChatPhoneMatch';
import { sortLeadChatMessagesChronologically } from './sortLeadChatMessagesChronologically';

/**
 * Merges outbound template send results into an open chat message list.
 * Returns { messages, mergedCount, needsRefetch }.
 */
export function mergeLeadChatTemplateSendResults({
  messages = [],
  results = [],
  activePhone,
  botNumber,
}) {
  if (!activePhone || !botNumber || !results.length) {
    return { messages, mergedCount: 0, needsRefetch: false };
  }

  let next = messages;
  let mergedCount = 0;
  let needsRefetch = false;

  results.forEach((detail) => {
    if (!detail?.success || detail.skipped) return;
    if (!leadChatPhonesMatch(activePhone, detail.phone)) return;
    if (!leadChatBotNumbersMatch(botNumber, detail.botNumber ?? botNumber)) return;

    if (detail.message) {
      const prev = next;
      next = applyIncomingMessage(next, detail.message, {
        activePhone,
        botNumber,
      });
      if (next !== prev) {
        mergedCount += 1;
      }
      return;
    }

    needsRefetch = true;
  });

  return {
    messages: mergedCount > 0 ? sortLeadChatMessagesChronologically(next) : next,
    mergedCount,
    needsRefetch: needsRefetch && mergedCount === 0,
  };
}
