import React, { useState } from 'react';
import { Box, Button, Stack, Tooltip, Typography } from '@mui/material';
import LeadMessageHeaderBlock from './LeadMessageHeaderBlock';
import LeadFormattedText from './LeadFormattedText';
import { LEAD_CHAT_COPY } from '../../constants/leadChatCopy';
import { useLeadChatAutomation } from '../../context/LeadChatAutomationContext';
import useLeadChatSx from '../../hooks/useLeadChatSx';

export default function ListMessage({ message }) {
  const sx = useLeadChatSx();
  const { isAutomationPaused } = useLeadChatAutomation();
  const [showOptions, setShowOptions] = useState(false);
  const { header, text, footer, listTitle, listOptions } = message;
  const hasOptions = listOptions?.length > 0;

  const listButton = (
    <Button
      variant="outlined"
      size="small"
      disabled={isAutomationPaused}
      onClick={() => setShowOptions((prev) => !prev)}
      sx={{
        ...sx.actionButton,
        ...(isAutomationPaused ? sx.actionButtonPaused : {}),
        flex: '0 0 auto',
        width: 'auto',
        minWidth: 120,
        maxWidth: '100%',
        textTransform: 'none',
        ...(showOptions ? { mb: 0.75 } : null),
      }}
    >
      {showOptions ? 'Hide list' : `View ${listTitle || 'Options'}`}
    </Button>
  );

  return (
    <Box sx={{ width: '100%', maxWidth: 300 }}>
      <LeadMessageHeaderBlock header={header} />
      {text ? <LeadFormattedText text={text} sx={{ mb: hasOptions ? 0.75 : 0 }} /> : null}

      {hasOptions ? (
        <>
          {isAutomationPaused ? (
            <Tooltip title={LEAD_CHAT_COPY.automation.listPausedTooltip} arrow placement="top">
              <Box component="span" sx={{ display: 'inline-flex' }}>
                {listButton}
              </Box>
            </Tooltip>
          ) : (
            listButton
          )}

          {showOptions && !isAutomationPaused ? (
            <Stack spacing={0.75} sx={{ mt: 0.75 }}>
              {listOptions.map((option, index) => (
                <Box
                  key={option.id || option.title || index}
                  sx={sx.listOptionCard}
                >
                  <Typography component="div" sx={sx.listOptionTitle}>
                    {option.title}
                  </Typography>
                  {option.description ? (
                    <Typography component="div" sx={sx.listOptionDescription}>
                      {option.description}
                    </Typography>
                  ) : null}
                </Box>
              ))}
            </Stack>
          ) : null}

          {isAutomationPaused ? (
            <Typography sx={{ ...sx.automationPausedHint, mt: 0.5 }}>
              {LEAD_CHAT_COPY.automation.customerActionsPaused}
            </Typography>
          ) : null}
        </>
      ) : null}

      {footer ? (
        <Typography variant="caption" sx={{ ...sx.messageFooter, mt: 0.5, display: 'block' }}>
          {footer}
        </Typography>
      ) : null}
    </Box>
  );
}
