import React from 'react';
import { Box } from '@mui/material';
import LeadFormattedText from './LeadFormattedText';
import MediaMessage from './MediaMessage';
import DocumentMessage from './DocumentMessage';
export default function LeadMessageHeaderBlock({ header, bleed = false }) {

  if (!header) return null;

  const bleedSx = bleed
    ? {
        mx: -0.25,
        '& video, & img': {
          borderRadius: '8px',
        },
      }
    : {};

  switch (header.kind) {
    case 'image':
    case 'video':
      return header.url ? (
        <Box sx={bleedSx}>
          <MediaMessage
            message={{
              kind: header.kind,
              media: { kind: header.kind, url: header.url },
            }}
          />
        </Box>
      ) : null;

    case 'document':
      return (
        <Box sx={bleedSx}>
          <DocumentMessage
            message={{
              kind: 'document',
              media: { kind: 'document', url: header.url, fileName: header.fileName },
            }}
          />
        </Box>
      );

    case 'text':
    default:
      return header.text ? (
        <LeadFormattedText
          text={header.text}
          sx={{ fontWeight: 600, mb: 0.25 }}
        />
      ) : null;
  }
}
