import { isValidNumber } from '../../../../utils/helper.jsx';
import { hydrateLegacyFormResponse } from '../../form-studio/adapters/formResponseAdapter';
import { normalizeFormItems } from './dynamicFilterUtils';
import { getRawLead, getRecordMongoId } from './recordInlineEditUtils';

function toWebFormShape(source, table) {
  if (!source) return null;
  return {
    leads_form_id: source.leads_form_id ?? table?.id ?? null,
    leads_form_name: source.leads_form_name ?? table?.name ?? '',
    leads_form_items: source.leads_form_items ?? [],
    group_options: source.group_options ?? source.groups ?? [],
    reference: source.reference ?? null,
    templates: source.templates ?? [],
  };
}

/**
 * Resolves a lead form definition from any API/table payload shape (Leads + Form Studio parity).
 */
export function resolveRecordFormDefinition(table, rawPayload = null) {
  const formId = table?.id ?? null;

  if (rawPayload) {
    const hydrated = hydrateLegacyFormResponse(rawPayload, { formId, injectStatic: true });
    if (normalizeFormItems(hydrated?.leads_form_items).length) {
      return toWebFormShape(hydrated, table);
    }
  }

  const tableItems = table?.leadsFormItems;
  if (normalizeFormItems(tableItems).length) {
    const hydrated = hydrateLegacyFormResponse(
      {
        leads_form_id: formId,
        leads_form_name: table?.name ?? '',
        leads_form_items: tableItems,
      },
      { formId, injectStatic: true }
    );
    if (normalizeFormItems(hydrated?.leads_form_items).length) {
      return toWebFormShape(hydrated, table);
    }
  }

  return null;
}

export function buildWebFormDefinition(table, rawPayload = null, formItems = null) {
  const resolved = resolveRecordFormDefinition(
    table,
    rawPayload ?? (normalizeFormItems(formItems).length ? { leads_form_items: formItems } : null)
  );
  if (resolved) return resolved;

  return {
    leads_form_id: table?.id ?? null,
    leads_form_name: table?.name ?? '',
    leads_form_items: [],
    group_options: [],
    reference: null,
    templates: [],
  };
}

export function hasWebFormDefinitionFields(webForm) {
  return normalizeFormItems(webForm?.leads_form_items).length > 0;
}

export function buildWebFormStoragePayload({
  workspaceId,
  table,
  formPayload,
  phoneNumber,
}) {
  const resolvedFormItems =
    formPayload?.leads_form_items
    ?? table?.leadsFormItems
    ?? {};

  return {
    campaign: {
      proposal_id: workspaceId,
      name: table?.campaignName || table?.name || 'Campaign',
    },
    phoneNumber,
    webForm: {
      ...(formPayload ?? {}),
      leads_form_id: table?.id ?? formPayload?.leads_form_id,
      leads_form_name: table?.name ?? formPayload?.leads_form_name,
      leads_form_items: resolvedFormItems,
    },
  };
}

export function openRecordWebForm({
  row,
  workspaceId,
  table,
  formPayload,
}) {
  const rawLead = getRawLead(row);
  const phoneNumber = rawLead?.phone_number ?? row?.phone_number ?? '';
  const recordId = getRecordMongoId(row);

  if (!phoneNumber || !isValidNumber(phoneNumber)) {
    return { ok: false, reason: 'invalidPhone' };
  }

  if (!workspaceId || !recordId) {
    return { ok: false, reason: 'missingContext' };
  }

  const payload = buildWebFormStoragePayload({
    workspaceId,
    table,
    formPayload,
    phoneNumber,
  });

  localStorage.setItem('leadWebFormData', JSON.stringify(payload));

  const url = `/r/lead-web-form/${encodeURIComponent(phoneNumber)}/${encodeURIComponent(recordId)}`;
  window.open(url, '_blank', 'noopener,noreferrer');

  return { ok: true };
}
