import React from 'react';
import { Box, Stack, Typography } from '@mui/material';
import LeadMessageHeaderBlock from './LeadMessageHeaderBlock';
import LeadFormattedText from './LeadFormattedText';
import LeadMessageActionButtons from './LeadMessageActionButtons';
import { formatLeadChatTemplateLabel } from '../../utils/leadChatDisplayUtils';
import useLeadChatSx from '../../hooks/useLeadChatSx';

export default function TemplateMessage({ message }) {
  const sx = useLeadChatSx();
  const template = message.template || {};
  const buttons = template.buttons?.length ? template.buttons : (message.buttons || []);
  const templateName = template.name || message.templateName;
  const typeLabel = formatLeadChatTemplateLabel(templateName);

  const hasStructuredHeader = Boolean(
    message.header?.url
    || message.header?.text
    || message.header?.fileName
    || message.header?.kind === 'document'
    || message.header?.kind === 'image'
    || message.header?.kind === 'video'
  );
  const textHeaderFallback = !hasStructuredHeader && template.header ? template.header : null;
  const bodyText = template.body || message.text;

  return (
    <Stack spacing={0.625} sx={{ width: '100%', maxWidth: 300 }}>
      <Typography component="span" sx={sx.templateLabel}>
        {typeLabel}
      </Typography>

      {hasStructuredHeader ? (
        <Box sx={{ mx: -0.25, mb: bodyText ? 0.375 : 0 }}>
          <LeadMessageHeaderBlock header={message.header} bleed />
        </Box>
      ) : null}

      {textHeaderFallback ? (
        <LeadFormattedText text={textHeaderFallback} sx={{ fontWeight: 600, mb: 0.25 }} />
      ) : null}

      {bodyText ? <LeadFormattedText text={bodyText} /> : null}

      {(template.footer || message.footer) ? (
        <Typography variant="caption" sx={sx.messageFooter}>
          {template.footer || message.footer}
        </Typography>
      ) : null}

      <LeadMessageActionButtons buttons={buttons} />
    </Stack>
  );
}
