import APIService from '../../../../Services/APIService';
import { Apis } from '../../../../Services/app.constants';

const MEDIA_HEADER_FORMATS = new Set(['IMAGE', 'VIDEO', 'DOCUMENT', 'AUDIO']);

const WHATSAPP_ALLOWED_MIME = {
  image: ['image/jpeg', 'image/png'],
  video: ['video/mp4', 'video/3gpp'],
  audio: ['audio/aac', 'audio/mp4', 'audio/mpeg', 'audio/amr', 'audio/ogg'],
  file: [
    'application/pdf',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'text/plain',
  ],
};

const WHATSAPP_LIMITS = {
  image: 5 * 1024 * 1024,
  video: 16 * 1024 * 1024,
  audio: 16 * 1024 * 1024,
  file: 100 * 1024 * 1024,
};

const BLOCKED_EXTENSIONS = new Set([
  '.exe', '.msi', '.cmd', '.bat', '.com', '.scr', '.dll',
  '.sh', '.bash', '.js', '.py', '.php', '.jar', '.apk',
]);

function inferDocType(mime) {
  if (WHATSAPP_ALLOWED_MIME.image.includes(mime)) return 'image';
  if (WHATSAPP_ALLOWED_MIME.video.includes(mime)) return 'video';
  if (WHATSAPP_ALLOWED_MIME.audio.includes(mime)) return 'audio';
  if (WHATSAPP_ALLOWED_MIME.file.includes(mime)) return 'file';
  return null;
}

function normalizeHeaderType(type) {
  return String(type || '').toUpperCase();
}

export function getLeadHeaderComponent(template) {
  const components = template?.components;
  if (!Array.isArray(components)) return null;
  return (
    components.find((component) => normalizeHeaderType(component?.type) === 'HEADER') || null
  );
}

export function getLeadTemplateHeaderFormat(template) {
  const format = getLeadHeaderComponent(template)?.format;
  return format ? normalizeHeaderType(format) : null;
}

export function needsLeadTemplateHeaderMedia(template) {
  const format = getLeadTemplateHeaderFormat(template);
  return Boolean(format && MEDIA_HEADER_FORMATS.has(format));
}

export function defaultUseTemplateHeaderMedia(template) {
  return Boolean(needsLeadTemplateHeaderMedia(template) && template?.media?.header);
}

export function getLeadHeaderAcceptValue(format) {
  if (format === 'IMAGE') return 'image/jpeg,image/png';
  if (format === 'VIDEO') return 'video/mp4,video/3gpp';
  if (format === 'DOCUMENT') return '.pdf,.doc,.docx,.xls,.xlsx,.txt';
  return '*/*';
}

export function validateLeadHeaderFile(file) {
  if (!file) return { valid: false, message: 'No file selected' };

  if (file.size <= 0) {
    return { valid: false, message: 'File cannot be empty. Please select a valid file.' };
  }

  const fileName = file.name?.toLowerCase() || '';
  const ext = fileName.includes('.') ? `.${fileName.split('.').pop()}` : '';

  if (BLOCKED_EXTENSIONS.has(ext)) {
    return { valid: false, message: `"${ext}" files are not allowed.` };
  }

  const typeGroup = inferDocType(file.type);
  if (!typeGroup) {
    return { valid: false, message: `Unsupported file type (${file.type || ext}).` };
  }

  const limit = WHATSAPP_LIMITS[typeGroup];
  if (file.size > limit) {
    const typeLabel = typeGroup === 'file' ? 'document' : typeGroup;
    const limitMB = Math.round(limit / (1024 * 1024));
    const sizeMB = (file.size / (1024 * 1024)).toFixed(2);
    return {
      valid: false,
      message: `File too large for ${typeLabel}. Max ${limitMB} MB. Your file is ${sizeMB} MB.`,
    };
  }

  return { valid: true };
}

export function validateLeadTemplateHeaderSend({
  template,
  headerFile,
  useTemplateHeaderMedia,
}) {
  if (!needsLeadTemplateHeaderMedia(template)) {
    return { valid: true, message: '' };
  }

  if (useTemplateHeaderMedia && template?.media?.header) {
    return { valid: true, message: '' };
  }

  if (headerFile) {
    return validateLeadHeaderFile(headerFile);
  }

  return {
    valid: false,
    message: 'Please upload a header file or use the template\'s uploaded header.',
  };
}

const PLACEHOLDER_CAPTIONS =
  /^(header\.(document|image|video|text|file)|(document|docuemnt)\.header)$/i;

function extractCaptionFromLink(link, fallback = '') {
  const rawName = link ? link.split('?')[0].split('/').pop() : '';
  const cleanFromLink = rawName.includes('_') ? rawName.slice(rawName.indexOf('_') + 1) : rawName;
  let caption = cleanFromLink;
  if (!caption && fallback && !PLACEHOLDER_CAPTIONS.test(fallback)) {
    caption = fallback;
  }
  try {
    caption = decodeURIComponent(caption);
  } catch (_) {}
  if (!caption || PLACEHOLDER_CAPTIONS.test(caption)) {
    caption = cleanFromLink || 'document';
  }
  return caption;
}

export function buildLeadTemplateSendPayload({
  formDataToSend,
  template,
  bodyParams,
  headerComponent,
  headerFileUrl,
  headerFileName,
  useTemplateHeaderMedia,
}) {
  const data = {
    ...formDataToSend,
    ts_id: template?.ts_id || '',
    name: template?.name,
    code: template?.language,
    components: [{ type: 'body', parameters: bodyParams }],
  };

  if (headerComponent) {
    const headerBlock = { type: 'header' };

    if ((useTemplateHeaderMedia || !headerFileUrl) && template?.media?.header) {
      const formatType = headerComponent.format?.toLowerCase();
      const mediaUrl = template.media.header;
      const caption = extractCaptionFromLink(
        mediaUrl,
        template?.media?.headerFilename
      );
      headerBlock.parameters = [{
        type: formatType,
        caption: formatType === 'image' ? 'autogenerated_caption.jpeg' : caption,
        link: mediaUrl,
      }];
    } else if (headerFileUrl) {
      const formatType = headerComponent.format?.toLowerCase();
      const caption = extractCaptionFromLink(
        headerFileUrl,
        headerFileName
      );
      headerBlock.parameters = [{
        type: formatType,
        caption: formatType === 'image' ? 'autogenerated_caption.jpeg' : caption,
        link: headerFileUrl,
      }];
    } else if (headerComponent.format === 'TEXT') {
      headerBlock.parameters = [{ type: 'text', text: headerComponent.text || 'header text' }];
    }

    if (headerBlock.parameters) {
      data.components.push(headerBlock);
    }
  }

  return data;
}

export async function uploadLeadTemplateHeaderFile(headerFile, botNumber) {
  const formData = new FormData();
  formData.append('file', headerFile);
  const url = `${Apis.uploadHeaderFile}?bot_number=${encodeURIComponent(botNumber)}`;
  const res = await APIService.post(url, formData, {
    'Content-Type': 'multipart/form-data',
  });
  if (res?.status !== 200) {
    return { ok: false, error: 'Error when uploading the header file' };
  }
  const payload = res?.data?.data ?? res?.data ?? {};
  const headerFileUrl = payload?.s3_object?.url ?? '';
  const headerFileName = extractCaptionFromLink(
    headerFileUrl,
    payload?.s3_object?.filename ?? payload?.filename ?? headerFile.name ?? ''
  );
  if (!headerFileUrl) {
    return { ok: false, error: 'Header file URL was not returned. Please retry upload.' };
  }
  return { ok: true, headerFileUrl, headerFileName };
}

export async function resolveLeadTemplateHeaderForSend({
  template,
  botNumber,
  headerFile,
  useTemplateHeaderMedia,
}) {
  const headerComponent = getLeadHeaderComponent(template);
  if (!headerComponent || !needsLeadTemplateHeaderMedia(template)) {
    return {
      headerComponent: null,
      headerFileUrl: '',
      headerFileName: '',
      useTemplateHeaderMedia: false,
    };
  }

  if (useTemplateHeaderMedia && template?.media?.header) {
    return {
      headerComponent,
      headerFileUrl: '',
      headerFileName: '',
      useTemplateHeaderMedia: true,
    };
  }

  if (!headerFile) {
    return {
      headerComponent,
      headerFileUrl: '',
      headerFileName: '',
      useTemplateHeaderMedia: false,
    };
  }

  const upload = await uploadLeadTemplateHeaderFile(headerFile, botNumber);
  if (!upload.ok) {
    return { error: upload.error };
  }

  return {
    headerComponent,
    headerFileUrl: upload.headerFileUrl,
    headerFileName: upload.headerFileName,
    useTemplateHeaderMedia: false,
  };
}

export async function postLeadTemplateSend(payload, botNumber) {
  return APIService.post(`${Apis.sendWhatsappTemplate}${botNumber}`, payload);
}

export function parseLeadTemplateSendError(response) {
  const root = response?.data ?? response;
  const errorData = root?.data ?? root;

  const generalError = errorData?.general_error;
  if (generalError !== undefined && generalError !== null) {
    if (typeof generalError === 'string') return generalError;
    const metaMessage = generalError?.error?.message;
    if (metaMessage) {
      const details = generalError?.error?.error_data?.details;
      return details ? `${metaMessage} — ${details}` : metaMessage;
    }
    if (generalError?.message) return generalError.message;
  }

  if (typeof errorData === 'string') return errorData;
  if (errorData?.message) return errorData.message;

  return 'Failed to send template';
}

export function resolveLeadTemplatePreviewHeaderUrl({
  headerFile,
  useTemplateHeaderMedia,
  template,
}) {
  if (headerFile) return null;
  if (useTemplateHeaderMedia && template?.media?.header) {
    return template.media.header;
  }
  return null;
}
