import React, { useCallback } from 'react';
import AIChatModal from '../../../../components/Leads/AIChatModal.tsx';
import AudioSummaryModal from '../../../../components/Leads/AudioSummaryModal.tsx';
import { getAiChatLeadId } from '../utils/recordInteractiveColumnUtils';

export default function ColumnModals({
  columnModals,
  onRecordUpdated,
}) {
  const {
    selectedRow,
    audioTranscriptList,
    setAudioTranscriptList,
    closeColumnModal,
    isAudioSummaryOpen,
    isAiChatOpen,
  } = columnModals;

  const handleAudioTableUpdate = useCallback(() => {
    onRecordUpdated?.();
  }, [onRecordUpdated]);

  return (
    <>
      {isAiChatOpen ? (
        <AIChatModal
          open={isAiChatOpen}
          onClose={closeColumnModal}
          leadId={getAiChatLeadId(selectedRow)}
        />
      ) : null}

      {isAudioSummaryOpen ? (
        <AudioSummaryModal
          open={isAudioSummaryOpen}
          onClose={closeColumnModal}
          rowData={selectedRow}
          setDataList={setAudioTranscriptList}
          dataList={audioTranscriptList}
          setTableState={handleAudioTableUpdate}
        />
      ) : null}
    </>
  );
}
