import React from 'react';
import { Box, Link, Typography } from '@mui/material';
import OpenInNewIcon from '@mui/icons-material/OpenInNew';
import { BadgeCell, TextCell } from '../../../../components/ui';
import { RECORD_COPY } from '../constants/recordCopy';
import {
  formatDuration,
  formatStatusLogDate,
  formatSummaryDate,
  getFirstValue,
  getResponseInfo,
  getStatusBadgeVariant,
  getStatusLabel,
  getSubStatusLabel,
  getSummaryDate,
  getTemplateNamesFromRow,
  getTriggeredBy,
  getTypeLabel,
} from '../utils/statusLogUtils';

export function buildStatusLogTableColumns({
  rows = [],
  selectedPayloadFields = [],
  onTemplateClick,
}) {
  const copy = RECORD_COPY.statusLogs.columns;

  const baseColumns = [
    {
      accessorKey: 'index',
      header: '#',
      size: 55,
      enableSorting: false,
      Cell: ({ row }) => row.index + 1,
    },
    {
      accessorKey: 'status_name',
      header: copy.status,
      size: 180,
      Cell: ({ row }) => {
        const label = getStatusLabel(row.original);
        return (
          <BadgeCell
            label={label}
            variant={getStatusBadgeVariant(label)}
            size="sm"
          />
        );
      },
    },
    {
      accessorKey: 'sub_status',
      header: copy.subStatus,
      size: 150,
      Cell: ({ row }) => (
        <BadgeCell label={getSubStatusLabel(row.original)} variant="neutral" size="sm" />
      ),
    },
    {
      accessorKey: 'status_type',
      header: copy.statusType,
      size: 120,
      Cell: ({ row }) => (
        <BadgeCell label={getTypeLabel(row.original)} variant="neutral" size="sm" />
      ),
    },
    {
      accessorKey: 'template_name',
      header: copy.template,
      size: 240,
      Cell: ({ row }) => {
        const names = getTemplateNamesFromRow(row.original);
        if (!names.length) {
          return <TextCell value="-" />;
        }

        return (
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, minWidth: 0 }}>
            {names.map((name, index) => (
              <Link
                key={`${name}-${index}`}
                component="button"
                underline="hover"
                onClick={() => onTemplateClick?.(row.original, name)}
                sx={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 0.5,
                  fontWeight: 600,
                  fontSize: '0.8125rem',
                  textAlign: 'left',
                  maxWidth: '100%',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap',
                }}
              >
                {name}
                <OpenInNewIcon sx={{ fontSize: 14, flexShrink: 0 }} />
              </Link>
            ))}
          </Box>
        );
      },
    },
    {
      accessorKey: 'created_by',
      header: copy.triggeredBy,
      size: 150,
      Cell: ({ row }) => <TextCell value={getTriggeredBy(row.original)} maxWidth="100%" />,
    },
    {
      accessorKey: 'updated_at',
      header: copy.triggeredOn,
      size: 180,
      Cell: ({ row }) => (
        <TextCell
          value={formatStatusLogDate(row.original.updated_at || row.original.created_at)}
          maxWidth="100%"
        />
      ),
    },
    {
      accessorKey: 'response_from_previous',
      header: copy.responseFrom,
      size: 180,
      Cell: ({ row }) => {
        const info = getResponseInfo(rows, row.index);
        return <TextCell value={info.from} maxWidth="100%" />;
      },
    },
    {
      accessorKey: 'response_time',
      header: copy.responseTime,
      size: 135,
      Cell: ({ row }) => {
        const info = getResponseInfo(rows, row.index);
        return <TextCell value={formatDuration(info.seconds)} maxWidth="100%" />;
      },
    },
    {
      accessorKey: 'comment',
      header: copy.comments,
      size: 260,
      Cell: ({ row }) => {
        const comments = row.original?.comments;
        if (Array.isArray(comments)) {
          return (
            <TextCell
              value={comments[comments.length - 1]?.comment || '-'}
              maxWidth="100%"
            />
          );
        }
        return <TextCell value={row.original?.comment || '-'} maxWidth="100%" />;
      },
    },
  ];

  const payloadColumns = selectedPayloadFields.map((key) => ({
    accessorKey: `payload.${key}`,
    header: `${copy.payloadPrefix}${key}`,
    size: 160,
    Cell: ({ row }) => {
      const value = row.original?.payload?.[key];
      if (value === null || value === undefined) return <TextCell value="-" />;
      const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
      return <TextCell value={text} maxWidth="100%" />;
    },
  }));

  return [...baseColumns, ...payloadColumns];
}

export function buildTemplateDateTableColumns({ onDateClick }) {
  const copy = RECORD_COPY.statusLogs.template.columns;

  return [
    {
      accessorKey: 'index',
      header: '#',
      size: 55,
      enableSorting: false,
      Cell: ({ row }) => row.index + 1,
    },
    {
      accessorKey: 'sent_date',
      header: copy.date,
      size: 180,
      Cell: ({ row }) => {
        const date = getSummaryDate(row.original);
        return (
          <Link
            component="button"
            underline="hover"
            onClick={() => onDateClick?.(row.original)}
            sx={{ fontWeight: 600, fontSize: '0.8125rem' }}
          >
            {formatSummaryDate(date)}
          </Link>
        );
      },
    },
    {
      accessorKey: 'total_users',
      header: copy.totalUsers,
      size: 130,
      Cell: ({ row }) => (
        <TextCell
          value={row.original.total_users ?? row.original.total ?? row.original.users ?? '-'}
        />
      ),
    },
    {
      accessorKey: 'delivered',
      header: copy.delivered,
      size: 120,
      Cell: ({ row }) => (
        <TextCell value={row.original.delivered ?? row.original.delivered_count ?? '-'} />
      ),
    },
    {
      accessorKey: 'read',
      header: copy.read,
      size: 120,
      Cell: ({ row }) => (
        <TextCell value={row.original.read ?? row.original.read_count ?? '-'} />
      ),
    },
    {
      accessorKey: 'clicked',
      header: copy.clicked,
      size: 120,
      Cell: ({ row }) => (
        <TextCell value={row.original.clicked ?? row.original.clicked_count ?? '-'} />
      ),
    },
    {
      accessorKey: 'failed',
      header: copy.failed,
      size: 120,
      Cell: ({ row }) => (
        <TextCell value={row.original.failed ?? row.original.failed_count ?? '-'} />
      ),
    },
  ];
}

function getUserValue(row, keys) {
  return getFirstValue(row, keys) || '-';
}

