import { templateService } from '../../../whatsapp-templates/services/templateService';
import { templateReportingService } from '../../../whatsapp-templates/services/templateReportingService';
import { mapDailyRowToSummaryRow } from '../../../whatsapp-templates/utils/reportingMappers';
import {
  extractResolvedTemplateId,
  getTemplateIdFromRow,
  normalizeStatusValue,
} from '../utils/statusLogUtils';

function normalizeDate(value) {
  if (!value) return '';

  const text = String(value);

  if (text.includes('T')) {
    return text.split('T')[0];
  }

  if (text.includes(' ')) {
    return text.split(' ')[0];
  }

  return text;
}

export const recordTemplateSummaryService = {
  async resolveTemplateId({
    row,
    templateName,
    botNumber = '',
  }) {
    const directId = getTemplateIdFromRow(row, templateName);

    if (directId) {
      return directId;
    }

    if (!templateName || !botNumber) {
      return '';
    }

    try {
      const response = await templateService.getTemplate(
        templateName,
        botNumber
      );

      if (
        response?.status !== 200 &&
        response?.status !== 201
      ) {
        return '';
      }

      const resolved = extractResolvedTemplateId(response);

      if (resolved) {
        return resolved;
      }

      const result = response?.data ?? response;

      if (Array.isArray(result)) {
        const matched =
          result.find(
            (item) =>
              normalizeStatusValue(
                item?.name || item?.template_name
              ) === normalizeStatusValue(templateName)
          ) || result[0];

        const arrayId =
          matched?.id ||
          matched?.template_id ||
          matched?.md_id ||
          '';

        return arrayId ? String(arrayId) : '';
      }

      return '';
    } catch {
      return '';
    }
  },

  async getDateWiseSummary(
    templateId,
    {
      companyId = '',
      botNumber = '',
      startDate = '',
      endDate = '',
    } = {}
  ) {
    if (!templateId) {
      throw new Error('Template ID is required');
    }

    if (!companyId) {
      throw new Error('Company ID is required');
    }

    const payload =
      await templateReportingService.getTemplateDaily(
        String(templateId),
        {
          company_id: companyId,
          bot_number: botNumber,
          template_id: String(templateId),
          start_date: normalizeDate(startDate),
          end_date: normalizeDate(endDate),
        },
        {
          page: 0,
          limit: 100,
        }
      );

    return (payload?.results ?? []).map((row) =>
      mapDailyRowToSummaryRow(
        row,
        String(templateId)
      )
    );
  },

  async getUserSummary(
    templateId,
    date,
    {
      companyId = '',
      botNumber = '',
      page = 0,
      limit = 100,
      search = '',
      status = '',
    } = {}
  ) {
    if (!templateId || !date) {
      return {
        users: [],
        total: 0,
        raw: null,
      };
    }

    if (!companyId) {
      throw new Error('Company ID is required');
    }

    const response =
      await templateReportingService.getRecipients(
        String(templateId),
        {
          company_id: companyId,
          bot_number: botNumber,
          template_id: String(templateId),
          sent_date: normalizeDate(date),
        },
        {
          page,
          limit,
        },
        {
          search,
          status,
        }
      );

    return {
      users: response?.results ?? [],
      total: Number(response?.total_count) || 0,
      raw: response,
    };
  },
};