import { normalizeUnreadPhone } from './leadChatUnreadUtils';

export function leadChatPhonesMatch(activePhone, incomingPhone) {
  if (!activePhone || !incomingPhone) return false;

  const cleanActive = `${normalizeUnreadPhone(activePhone)}`.replace(/\D/g, '');
  const cleanIncoming = `${normalizeUnreadPhone(incomingPhone)}`.replace(/\D/g, '');

  if (!cleanActive || !cleanIncoming) return false;

  return (
    cleanActive === cleanIncoming
    || (cleanActive.length >= 10
      && cleanIncoming.length >= 10
      && cleanActive.slice(-10) === cleanIncoming.slice(-10))
  );
}

export function leadChatBotNumbersMatch(expectedBot, incomingBot) {
  if (!expectedBot || !incomingBot) return true;
  return `${expectedBot}`.replace(/\D/g, '') === `${incomingBot}`.replace(/\D/g, '');
}
