import { dateFormate, indianTimeZone } from '../../../../utils/helper.jsx';
import { getRawLead } from './recordInlineEditUtils';

export function formatRecordCreatedAt(value) {
  if (!value) return '';
  return indianTimeZone(value).format('DD-MM-YYYY, h:mm A');
}

export function getRecordLeadDisplayId(row) {
  const rawLead = getRawLead(row);
  return rawLead?.lead_id ?? row?.lead_id ?? '';
}

export function getRecordPhoneNumber(row) {
  const rawLead = getRawLead(row);
  return rawLead?.phone_number ?? row?.phone_number ?? '';
}

export function getAiChatLeadId(row) {
  const rawLead = getRawLead(row);
  return rawLead?.c_id || rawLead?.lead_id || '';
}

export function hasAiChatData(row) {
  const rawLead = getRawLead(row);
  if (!rawLead) return false;
  if (rawLead.flow_type === 'AI') return true;
  return Array.isArray(rawLead.aichat) && rawLead.aichat.length > 0;
}

export function hasAudioSummaryTranscript(row) {
  const rawLead = getRawLead(row);
  return Boolean(rawLead?.audio_summary?.transcript);
}

export const COMMENT_COLUMN_KEY = 'last_machadalo_comment.comment';

export function isCommentColumnKey(keyName) {
  return keyName === COMMENT_COLUMN_KEY || keyName === 'comment';
}

export function getLastCommentText(row) {
  const rawLead = getRawLead(row);
  const comment = rawLead?.last_machadalo_comment;

  if (Array.isArray(comment)) {
    return comment[0]?.comment ?? '';
  }

  if (comment && typeof comment === 'object') {
    return comment.comment ?? '';
  }

  return '';
}

export function formatRecordDateValue(value, fieldMeta) {
  if (fieldMeta?.key_name === 'created_at') {
    return formatRecordCreatedAt(value);
  }

  return dateFormate(value, 'DD-MM-YYYY');
}
