import { useCallback, useState } from 'react';
import { useSnackBar } from '../../../../components/FlowBuilder/Common/SnackBar/index.tsx';
import { convertToReadableFormat } from '../../../../utils/helper.jsx';
import { recordService } from '../services/recordService';
import { RECORD_COPY } from '../constants/recordCopy';
import {
  buildClearLinkedSubStatusPayloads,
  getDependentEntityFieldKeys,
  buildInlineStatusPayload,
  buildLeadPayloadForEntityUpdate,
  getRawLead,
} from '../utils/recordInlineEditUtils';

export default function useInlineEdit({ tableId, formItems = [], onSuccess }) {
  const { showSnackBar } = useSnackBar();
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [pendingStatusUpdate, setPendingStatusUpdate] = useState(null);
  const [isUpdating, setIsUpdating] = useState(false);

  const requestStatusUpdate = useCallback((row, selected, fieldMeta) => {
    const payload = buildInlineStatusPayload(row, selected, fieldMeta);
    if (!payload?.id) {
      showSnackBar('Unable to update status for this record', 'error');
      return;
    }

    setPendingStatusUpdate({
      row,
      fieldMeta,
      payload,
    });
    setConfirmOpen(true);
  }, [showSnackBar]);

  const closeConfirm = useCallback(() => {
    if (isUpdating) return;
    setConfirmOpen(false);
    setPendingStatusUpdate(null);
  }, [isUpdating]);

  const confirmStatusUpdate = useCallback(async () => {
    if (!pendingStatusUpdate?.payload) {
      closeConfirm();
      return;
    }

    setIsUpdating(true);
    try {
      const res = await recordService.updateLeadStatus(pendingStatusUpdate.payload);
      if (res?.status !== 200) {
        showSnackBar('Failed to update status', 'error');
        return;
      }

      const clearPayloads = buildClearLinkedSubStatusPayloads(
        pendingStatusUpdate.row,
        pendingStatusUpdate.fieldMeta,
        formItems
      );

      for (const clearPayload of clearPayloads) {
        await recordService.updateLeadStatus(clearPayload);
      }

      showSnackBar(RECORD_COPY.success.statusUpdated, 'success');
      onSuccess?.();
      setConfirmOpen(false);
      setPendingStatusUpdate(null);
    } catch {
      showSnackBar('Failed to update status', 'error');
    } finally {
      setIsUpdating(false);
    }
  }, [closeConfirm, formItems, onSuccess, pendingStatusUpdate, showSnackBar]);

  const updateEntity = useCallback(async (row, fieldMeta, selectedOption) => {
    const rawLead = getRawLead(row);
    if (!rawLead) return;

    const prevData = rawLead?.data ?? [];
    const dependentFieldKeys = getDependentEntityFieldKeys(fieldMeta, formItems);
    const updatedData = prevData.map((item) => {
      if (item?.key_name !== fieldMeta?.key_name) return item;
      if (!selectedOption) {
        return { ...item, value: '', entity_data: null };
      }
      return {
        ...item,
        value: selectedOption?._id ?? '',
        entity_data: {
          _id: selectedOption?._id ?? '',
          value: selectedOption?.value ?? '',
        },
      };
    }).map((item) => {
      if (!dependentFieldKeys.has(item?.key_name)) return item;
      return { ...item, value: '', entity_data: null };
    });

    try {
      const payload = buildLeadPayloadForEntityUpdate(rawLead, updatedData, tableId);
      const res = await recordService.updateRecord(payload);
      if (res?.status === 200) {
        showSnackBar(RECORD_COPY.success.entityUpdated, 'success');
        onSuccess?.();
      } else {
        showSnackBar('Failed to update entity', 'error');
      }
    } catch {
      showSnackBar('Failed to update entity', 'error');
    }
  }, [formItems, onSuccess, showSnackBar, tableId]);

  const confirmTitle = pendingStatusUpdate?.fieldMeta?.key_name
    ? `Update ${convertToReadableFormat(pendingStatusUpdate.fieldMeta.key_name)}`
    : 'Update status';

  const confirmMessage = (() => {
    const typeLabel = convertToReadableFormat(
      pendingStatusUpdate?.payload?.type_of_status || 'Status'
    );
    const nextValue =
      pendingStatusUpdate?.payload?.sub_status_name
      || pendingStatusUpdate?.payload?.status_name
      || '';

    if (nextValue) {
      return `Are you sure you want to update ${typeLabel} to "${nextValue}"?`;
    }

    return `Are you sure you want to update ${typeLabel}?`;
  })();

  return {
    confirmOpen,
    confirmTitle,
    confirmMessage,
    isUpdating,
    requestStatusUpdate,
    confirmStatusUpdate,
    closeConfirm,
    updateEntity,
  };
}
