const PLACEHOLDER_FILE_NAMES =
  /^(header\.(document|image|video|text|file)|(document|docuemnt)\.header|\{\{\s*\d+\s*\}\}|document|file|media)$/i;

function extractFileNameFromUrl(url) {
  if (!url) return null;
  const raw = url.split('?')[0].split('/').pop() || '';
  const clean = raw.includes('_') ? raw.slice(raw.indexOf('_') + 1) : raw;
  try {
    return decodeURIComponent(clean) || null;
  } catch (_) {
    return clean || null;
  }
}

export function sanitizeLeadChatFileName(fileName, fallback = 'Document', url = null) {
  const trimmed = `${fileName || ''}`.trim();
  if (!trimmed || PLACEHOLDER_FILE_NAMES.test(trimmed)) {
    return (url ? extractFileNameFromUrl(url) : null) || fallback;
  }
  return trimmed;
}

export function formatLeadChatTemplateLabel(templateName) {
  if (!templateName) return 'Template';
  return `${templateName}`
    .replace(/_/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase()
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

export function isLeadChatRichMessageKind(kind) {
  return kind === 'template' || kind === 'buttons' || kind === 'list';
}
