import React, { useEffect, useMemo, useState } from 'react';
import { Alert, Box, Tab, Tabs, useMediaQuery, useTheme } from '@mui/material';
import { Button, Dialog, EmptyState } from '../../../../components/ui';
import { useFeatureTheme } from '../../../../theme/hooks/useFeatureTheme';
import useLeanBulkSend from '../../../whatsapp-templates/hooks/useLeanBulkSend';
import useLeadTemplateSend from '../hooks/useLeadTemplateSend';
import LeadSendTemplateBulkView from './LeadSendTemplateBulkView';
import LeadSendTemplateFieldSelects from './LeadSendTemplateFieldSelects';
import LeadSendTemplateIndividualView from './LeadSendTemplateIndividualView';

export default function LeadSendTemplateModal({
  open,
  onClose,
  selectedRows = [],
  formPayload,
  columnsMeta = [],
  organisationId,
  styles,
  onSuccess,
}) {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const isSplitStacked = useMediaQuery(theme.breakpoints.down('md'));
  const { semantic } = useFeatureTheme();

  const sendState = useLeadTemplateSend({
    open,
    selectedRows,
    formPayload,
    columnsMeta,
    organisationId,
    onSuccess,
    onClose,
  });

  const {
    copy,
    subtitle,
    selectedCount,
    botNumber,
    hasNoBots,
    quickTemplates,
    selectedTemplateMeta,
    resolvedTemplate,
    isLoadingTemplate,
    isSubmitting,
    sendProgress,
    sendSummary,
    coverage,
    liveBodyParams,
    isSingleRecipient,
    bulkMappingFields,
    gapLines,
    editableFields,
    columnOptions,
    canSendDirect,
    handleParamChange,
    handleParamColumnSelect,
    selectQuickTemplate,
    handleTemplateDropdownChange,
    handleBotChange,
    sendDirect,
    queueMappedLeads,
    headerFile,
    useTemplateHeaderMedia,
    headerFormat,
    headerValidationError,
    onHeaderFileSelect,
    onHeaderFileRemove,
    onUseTemplateHeaderChange,
  } = sendState;

  const [tab, setTab] = useState(isSingleRecipient ? 0 : 1);
  useEffect(() => {
    if (open) setTab(isSingleRecipient ? 0 : 1);
  }, [isSingleRecipient, open]);
  const leanTemplate = useMemo(
    () => (resolvedTemplate ? { ...resolvedTemplate, bot_number: botNumber } : null),
    [botNumber, resolvedTemplate]
  );
  const leanSend = useLeanBulkSend({ template: leanTemplate });

  const isBusy = isSubmitting || leanSend.isUploadLoading || leanSend.isDiscardLoading;
  const botValue = useMemo(
    () => (botNumber ? { wa_phone_number: botNumber } : null),
    [botNumber]
  );

  const handleClose = () => {
    if (isBusy) return;
    onClose?.();
  };

  const primaryLabel = copy.direct.sendNow;
  const showPrimaryAction = isSingleRecipient && tab === 0;

  const footer = (
    <Box sx={styles?.leadSendTemplateFooterActions}>
      <Button variant="ghost" onClick={handleClose} disabled={isBusy}>
        {copy.cancel}
      </Button>
      {showPrimaryAction ? (
        <Button
          variant="primary"
          loading={isSubmitting}
          disabled={!canSendDirect || isLoadingTemplate || isBusy}
          onClick={sendDirect}
        >
          {primaryLabel}
        </Button>
      ) : null}
    </Box>
  );

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      title={copy.title}
      subtitle={subtitle}
      maxWidth="lg"
      fullWidth
      fullScreen={isMobile}
      actions={footer}
      contentSx={{
        px: { xs: 2, sm: 2.5 },
        py: { xs: 1.5, sm: 2 },
        display: 'flex',
        flexDirection: 'column',
        minHeight: 0,
        maxHeight: isMobile ? 'none' : 'min(92vh, 820px)',
        overflow: 'auto',
        bgcolor: semantic.surfaces.background,
      }}
    >
      <Box sx={styles?.leadSendTemplateModalContent}>
        <Box sx={styles?.leadSendTemplateSetupSection}>
        <LeadSendTemplateFieldSelects
          organisationId={organisationId}
          botNumber={botNumber}
          botValue={botValue}
          selectedTemplateMeta={selectedTemplateMeta}
          onBotChange={handleBotChange}
          onTemplateChange={handleTemplateDropdownChange}
          botLabel={copy.botLabel}
          templateLabel={copy.templateLabel}
          disabled={isBusy}
        />

        {!botNumber && hasNoBots ? (
          <EmptyState
            title={copy.empty.noBots}
            description={copy.empty.noBotsDescription}
          />
        ) : null}

        {!botNumber && !hasNoBots ? (
          <EmptyState
            title={copy.empty.noBot}
            description={copy.empty.noBotDescription}
          />
        ) : null}

        {botNumber && !isLoadingTemplate && !resolvedTemplate && selectedTemplateMeta ? (
          <Alert severity="error">{copy.templateLoadFailed}</Alert>
        ) : null}

        {quickTemplates.length ? (
          <Box>
            <Box sx={{ mb: 0.75, color: semantic.text.secondary, fontSize: '0.875rem' }}>
              {copy.quickTemplates}
            </Box>
            <Box sx={styles?.leadSendTemplateChipRow}>
              {quickTemplates.map((template) => {
                const isSelected = selectedTemplateMeta?.name === template?.name;
                return (
                  <Button
                    key={template?.name ?? template?.id}
                    variant={isSelected ? 'primary' : 'outline'}
                    size="sm"
                    onClick={() => selectQuickTemplate(template)}
                    sx={{ minHeight: 44, flexShrink: 0 }}
                  >
                    {template?.name ?? template?.label}
                  </Button>
                );
              })}
            </Box>
          </Box>
        ) : null}
        </Box>

        {resolvedTemplate && coverage && !hasNoBots ? (
          <>
            <Tabs value={tab} onChange={(_event, value) => setTab(value)}>
              <Tab label="Single Send" />
              <Tab label="Bulk Send" />
            </Tabs>
            {tab === 0 ? (
              isSingleRecipient ? (
                <LeadSendTemplateIndividualView
                  copy={copy}
                  styles={styles}
                  template={resolvedTemplate}
                  liveBodyParams={liveBodyParams}
                  editableFields={editableFields}
                  columnOptions={columnOptions}
                  coverage={coverage}
                  isSubmitting={isSubmitting}
                  sendProgress={sendProgress}
                  sendSummary={sendSummary}
                  onParamChange={handleParamChange}
                  onColumnSelect={handleParamColumnSelect}
                  stackFields={isSplitStacked}
                  headerFile={headerFile}
                  useTemplateHeaderMedia={useTemplateHeaderMedia}
                  headerFormat={headerFormat}
                  headerValidationError={headerValidationError}
                  onHeaderFileSelect={onHeaderFileSelect}
                  onHeaderFileRemove={onHeaderFileRemove}
                  onUseTemplateHeaderChange={onUseTemplateHeaderChange}
                />
              ) : (
                <EmptyState
                  title="Use Bulk Send"
                  description="More than one record is selected. Map columns on the Bulk Send tab, then queue them."
                />
              )
            ) : (
              <LeadSendTemplateBulkView
                copy={copy}
                styles={styles}
                template={leanTemplate}
                selectedCount={selectedCount}
                liveBodyParams={liveBodyParams}
                bulkMappingFields={bulkMappingFields}
                columnOptions={columnOptions}
                coverage={coverage}
                gapLines={gapLines}
                onColumnSelect={handleParamColumnSelect}
                onQueueSelected={() => queueMappedLeads(leanSend.uploadPreparedFile)}
                isQueueing={leanSend.isUploadLoading}
                leanSend={leanSend}
              />
            )}
          </>
        ) : null}

        {botNumber && !selectedTemplateMeta && !quickTemplates.length ? (
          <EmptyState
            title={copy.empty.noTemplates}
            description={copy.empty.noTemplatesDescription}
          />
        ) : null}
      </Box>
    </Dialog>
  );
}
