import React from 'react';
import { Box, Tooltip, Typography } from '@mui/material';
import { LEAD_CHAT_COPY } from '../../constants/leadChatCopy';
import { useLeadChatAutomation } from '../../context/LeadChatAutomationContext';
import useLeadChatSx from '../../hooks/useLeadChatSx';

function isUrlButton(button) {
  const type = `${button.type || ''}`.toUpperCase();
  return type.includes('URL') || Boolean(button.url);
}

export default function LeadMessageActionButtons({
  buttons = [],
  disabled = false,
}) {
  const sx = useLeadChatSx();
  const { isAutomationPaused } = useLeadChatAutomation();

  if (!buttons.length) return null;

  return (
    <Box sx={sx.actionButtonList}>
      {buttons.map((button, index) => {
        const label = button.label || button.title || button.text || 'Button';
        const key = button.id || button.url || `${label}-${index}`;
        const isDisabled = disabled || isAutomationPaused || button.disabled;
        const tooltip = isAutomationPaused
          ? LEAD_CHAT_COPY.automation.buttonPausedTooltip
          : (label || '');

        const buttonNode = (
          <Box
            component="button"
            type="button"
            disabled={isDisabled}
            aria-disabled={isDisabled}
            title={!isAutomationPaused ? label : undefined}
            sx={{
              ...sx.actionButton,
              ...(isDisabled ? sx.actionButtonPaused : {}),
              cursor: isDisabled ? 'not-allowed' : 'default',
              opacity: isDisabled ? 0.72 : 1,
            }}
          >
            {label}
          </Box>
        );

        return (
          <Tooltip key={key} title={tooltip} arrow placement="top">
            <Box component="span" sx={{ display: 'block', width: '100%' }}>
              {buttonNode}
            </Box>
          </Tooltip>
        );
      })}

      {isAutomationPaused ? (
        <Typography sx={sx.automationPausedHint}>
          {LEAD_CHAT_COPY.automation.customerActionsPaused}
        </Typography>
      ) : null}
    </Box>
  );
}
