import { getMessageTimestampMs } from '../../../../intervene/utils/normalizeMessageTimestamp';

export function sortLeadChatMessagesChronologically(messages = []) {
  if (!messages.length) return messages;

  return [...messages].sort((left, right) => {
    const leftTs = getMessageTimestampMs(left);
    const rightTs = getMessageTimestampMs(right);

    if (leftTs != null && rightTs != null && leftTs !== rightTs) {
      return leftTs - rightTs;
    }
    if (leftTs != null && rightTs == null) return -1;
    if (leftTs == null && rightTs != null) return 1;

    const leftId = String(left?.msg_id || left?.w_id || left?.c_id || '');
    const rightId = String(right?.msg_id || right?.w_id || right?.c_id || '');
    return leftId.localeCompare(rightId);
  });
}
