import { useEffect } from 'react';
import { useLeadChatTemplateSyncOptional } from '../context/LeadChatTemplateSyncContext';
import { mergeLeadChatTemplateSendResults } from '../utils/mergeLeadChatTemplateSendResults';

export default function useLeadChatTemplateSendSync({
  open,
  chatContext,
  messagesRef,
  pagination,
  dispatch,
  loadMessages,
  shouldStickToBottomRef,
  scrollToBottom,
}) {
  const sync = useLeadChatTemplateSyncOptional();

  useEffect(() => {
    if (!sync || !open) {
      sync?.registerTemplateSendSync(null);
      return undefined;
    }

    const handler = ({ results = [], botNumber } = {}) => {
      if (!chatContext?.phoneNumber || !botNumber) return;

      const activeBot = chatContext.botNumber || botNumber;
      if (
        chatContext.botNumber
        && `${chatContext.botNumber}`.replace(/\D/g, '') !== `${botNumber}`.replace(/\D/g, '')
      ) {
        return;
      }

      const { messages, mergedCount, needsRefetch } = mergeLeadChatTemplateSendResults({
        messages: messagesRef.current,
        results,
        activePhone: chatContext.phoneNumber,
        botNumber: activeBot,
      });

      if (mergedCount > 0) {
        shouldStickToBottomRef.current = true;
        dispatch({
          type: 'SET_MESSAGES',
          payload: {
            messages,
            pagination,
          },
        });
        requestAnimationFrame(() => scrollToBottom?.());
        return;
      }

      if (needsRefetch) {
        shouldStickToBottomRef.current = true;
        Promise.resolve(loadMessages(1, { silent: true, stickToBottom: true })).finally(() => {
          scrollToBottom?.();
        });
      }
    };

    sync.registerTemplateSendSync(handler);
    return () => sync.registerTemplateSendSync(null);
  }, [
    sync,
    open,
    chatContext?.phoneNumber,
    chatContext?.botNumber,
    dispatch,
    loadMessages,
    messagesRef,
    pagination,
    shouldStickToBottomRef,
    scrollToBottom,
  ]);
}
