import { useCallback, useEffect, useLayoutEffect, useRef } from 'react';
import { scrollLeadChatFeedToBottom } from '../utils/scrollLeadChatFeedToBottom';

export default function useLeadChatScroll({
  messages,
  isLoadingMessages,
  isLoadingOlder,
  hasMoreMessages,
  onLoadOlderMessages,
  shouldStickToBottomRef,
  activePhone,
}) {
  const scrollRef = useRef(null);
  const prevScrollHeightRef = useRef(0);

  const scrollToBottom = useCallback(() => {
    if (shouldStickToBottomRef) {
      shouldStickToBottomRef.current = true;
    }
    scrollLeadChatFeedToBottom(scrollRef.current);
  }, [shouldStickToBottomRef]);

  const handleScroll = useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;

    if (el.scrollTop < 80 && hasMoreMessages && !isLoadingOlder) {
      prevScrollHeightRef.current = el.scrollHeight;
      onLoadOlderMessages?.();
    }

    const distanceFromBottom = el.scrollHeight - el.scrollTop - el.clientHeight;
    if (shouldStickToBottomRef) {
      shouldStickToBottomRef.current = distanceFromBottom < 80;
    }
  }, [hasMoreMessages, isLoadingOlder, onLoadOlderMessages, shouldStickToBottomRef]);

  useLayoutEffect(() => {
    const el = scrollRef.current;
    if (!el) return;

    if (isLoadingOlder && prevScrollHeightRef.current) {
      const delta = el.scrollHeight - prevScrollHeightRef.current;
      el.scrollTop = delta;
      prevScrollHeightRef.current = 0;
      return;
    }

    if (shouldStickToBottomRef?.current && !isLoadingMessages) {
      scrollLeadChatFeedToBottom(el);
    }
  }, [messages, isLoadingMessages, isLoadingOlder, shouldStickToBottomRef]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollLeadChatFeedToBottom(scrollRef.current);
    }
  }, [activePhone]);

  return { scrollRef, handleScroll, scrollToBottom };
}
